import json
from collections import defaultdict
d=json.load(open('graphify-out/graph.json'))
nodes={n['id']:n for n in d['nodes']}
edges=d['links']
callers=defaultdict(set)
for e in edges:
    if e.get('relation') in ('calls','indirect_call'):
        callers[e['target']].add(e['source'])
rows=[]
for tid,cs in callers.items():
    n=nodes.get(tid)
    if n and str(n.get('source_file','')).startswith('internal/'):
        rows.append((len(cs), n['label'], n['source_file'], n['source_location'], tid))
rows.sort(reverse=True)
for r in rows[:15]:
    print(r[0], r[1], r[2]+':'+str(r[3]))
"

